import{_ as a,o as t,c as i,a2 as n}from"./chunks/framework.mRCPFc5l.js";const m=JSON.parse('{"title":"Inviting people","description":"Invite people to a Space, manage invitations, and revoke access again.","frontmatter":{"title":"Inviting people","description":"Invite people to a Space, manage invitations, and revoke access again."},"headers":[],"relativePath":"en/zusammenarbeit/personen-einladen.md","filePath":"en/zusammenarbeit/personen-einladen.md","lastUpdated":1787319236000}'),s={name:"en/zusammenarbeit/personen-einladen.md"};function o(r,e,l,h,p,d){return t(),i("div",null,[...e[0]||(e[0]=[n('<h1 id="inviting-people" tabindex="-1">Inviting people <a class="header-anchor" href="#inviting-people" aria-label="Permalink to &quot;Inviting people&quot;">​</a></h1><p>Collaboration in ApptiveGrid always happens at the <strong>Space</strong> level. You don&#39;t invite people to a single Grid or form, but to the entire Space.</p><div class="warning custom-block"><p class="custom-block-title">An invitation applies to the whole Space</p><p>Whoever has access to a Space sees all Grids, pages, and Flows in it — within the limits of their role.</p><p>If certain people should only see a subset, there are two ways:</p><ol><li>Put the data in a <strong>separate Space</strong>.</li><li>Instead of an invitation, provide a <a href="/en/zusammenarbeit/zugriff-beschraenken">shared view or a portal</a>.</li></ol></div><h2 id="inviting-a-person" tabindex="-1">Inviting a person <a class="header-anchor" href="#inviting-a-person" aria-label="Permalink to &quot;Inviting a person&quot;">​</a></h2><ol><li>Open the Space.</li><li>Choose <strong>Share Space</strong>.</li><li>Enter the email address.</li><li>Choose the <a href="/en/zusammenarbeit/rollen">role</a>.</li><li>Send the invitation.</li></ol><p>The person receives an email with an invitation link.</p><h2 id="managing-invitations" tabindex="-1">Managing invitations <a class="header-anchor" href="#managing-invitations" aria-label="Permalink to &quot;Managing invitations&quot;">​</a></h2><p>The share dialog shows two lists:</p><ul><li><strong>Shared with</strong> — people who already have access, along with their role</li><li><strong>Pending invitations</strong> — invitations sent but not yet accepted</li></ul><p>You change a person&#39;s role directly in the first list. The change takes effect immediately.</p><h2 id="revoking-access" tabindex="-1">Revoking access <a class="header-anchor" href="#revoking-access" aria-label="Permalink to &quot;Revoking access&quot;">​</a></h2><p>Remove the person from <strong>Shared with</strong>. Their access ends immediately.</p><div class="tip custom-block"><p class="custom-block-title">Existing entries remain</p><p>Entries the person created stay in place. The <em>Created by</em> column still shows their name.</p></div><div class="warning custom-block"><p class="custom-block-title">Shared links stay active</p><p>Removing a person only ends their Space access. Form and view links they created or received keep working.</p><p>After someone leaves, check the <a href="/en/zusammenarbeit/externe-links">links overview</a> of the Space.</p></div><h2 id="common-error-messages" tabindex="-1">Common error messages <a class="header-anchor" href="#common-error-messages" aria-label="Permalink to &quot;Common error messages&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Message</th><th>Cause</th></tr></thead><tbody><tr><td><em>This Space is already shared with this user</em></td><td>The person already has access. Change their role in the <em>Shared with</em> list instead.</td></tr><tr><td><em>Spaces cannot be shared with themselves</em></td><td>You entered your own address.</td></tr><tr><td><em>User with email {email} does not exist</em></td><td>There&#39;s no ApptiveGrid account for this address. Check the spelling; otherwise the person must register first.</td></tr></tbody></table><h2 id="when-seats-run-out" tabindex="-1">When seats run out <a class="header-anchor" href="#when-seats-run-out" aria-label="Permalink to &quot;When seats run out&quot;">​</a></h2><p>People with editing rights occupy a <strong>seat</strong>. If the available seats aren&#39;t enough, ApptiveGrid reports:</p><blockquote><p><em>Exceeded the licensed seats in your plan</em></p><p><em>Change users&#39; permissions to &quot;Read only&quot; or book additional seats.</em></p></blockquote><p><strong>Read-only access is free</strong> and doesn&#39;t take up a seat. Often that&#39;s already the solution: anyone who only needs to view data doesn&#39;t need editing rights.</p><p>→ <a href="/en/zusammenarbeit/sitzplaetze">Seats</a></p><h2 id="accepting-an-invitation" tabindex="-1">Accepting an invitation <a class="header-anchor" href="#accepting-an-invitation" aria-label="Permalink to &quot;Accepting an invitation&quot;">​</a></h2><p>Whoever is invited clicks the link in the email and signs in or registers. Afterward, the Space appears in their overview under <strong>Shared with me</strong>.</p><h2 id="next" tabindex="-1">Next <a class="header-anchor" href="#next" aria-label="Permalink to &quot;Next&quot;">​</a></h2><ul><li><a href="/en/zusammenarbeit/rollen">Roles</a></li><li><a href="/en/zusammenarbeit/sitzplaetze">Seats</a></li><li><a href="/en/zusammenarbeit/zugriff-beschraenken">Access to shared content</a></li></ul>',25)])])}const g=a(s,[["render",o]]);export{m as __pageData,g as default};
